api.bind = ["Complex", "Building", "Floor", "Unit", "Room"];
var sites_state;
if(!api.getValue("_sites_state")){
    sites_state = [{
      site: "Room",
      value: api.getValue("Room")
    },{
        site: 'Unit',
        value: api.getValue("Unit")
    },{
        site: 'Floor',
        value: api.getValue("Floor")
    },{
        site: 'Building',
        value: api.getValue("Building")
    },{
        site: 'Complex',
        value: api.getValue("Complex")
    }];
}else {
    sites_state = api.getValue("_sites_state");
}


//Check if there are any changes
var changed = sites_state.find(function(card){
    var oldValue = card.value;
    var newValue = api.getValue(card.site);
    return newValue != oldValue;    
});

if(changed){
    changed.value = api.getValue(changed.site);
    //if the attribute is valorized then valorize all attributes
    if(!Ext.isEmpty(changed.value)){
        api.getRemoteCard(changed.site, changed.value).then(function(card){
            sites_state.slice(sites_state.indexOf(changed) + 1).forEach(function (record){
                var value = card.get(record.site);
                api.setValue(record.site, value);
                record.value = value;
            });
        });
    //otherwise set child attributes to null    
    }else{
        for(let i = sites_state.indexOf(changed) - 1; i >= 0; i--){
            api.setValue(sites_state[i].site, null);
            sites_state[i].value = null;
        }
    }
}

api.record.set("_sites_state", sites_state);

